from __future__ import annotations
import json,re
from ..database import DB,Database
from ..utils import escape

READER_CSS=r'''
:root{--paper:#fff;--ink:#24232a;--muted:#777583;--line:#e8e5ef;--accent:#7357d7;--accent-soft:#f2edff;--font-scale:1;color-scheme:light}html[data-theme=dark]{--paper:#17161b;--ink:#eceaf1;--muted:#aaa5b2;--line:#3b3743;--accent:#b69aef;--accent-soft:#2b243a;color-scheme:dark}
*{box-sizing:border-box}html{background:var(--paper);color:var(--ink);font-family:Inter,system-ui,-apple-system,"Segoe UI",sans-serif;line-height:1.68;scroll-behavior:smooth}body{margin:0 auto;max-width:860px;padding:42px 58px 120px;font-size:calc(18px * var(--font-scale))}h1{font-size:2.08rem;line-height:1.16;margin:.25em 0 .75em}h2{font-size:1.48rem;line-height:1.28;margin:1.7em 0 .65em}h3{font-size:1.18rem}p{margin:.78em 0}a{color:#6747cc;text-decoration:none}a:hover{text-decoration:underline}figure{margin:1.6em auto;text-align:center}img,svg,video{max-width:100%;height:auto;border-radius:12px}figcaption,.figcaption{color:var(--muted);font-size:.88rem;margin-top:.55rem}.pageNum{display:none}.boxContent,.boxSupplement,.studyQuestion{border-left:4px solid var(--accent);background:var(--accent-soft);padding:14px 18px;border-radius:9px;margin:1.2em 0}.groupTOC{display:grid;gap:.25rem}.groupTOC p{margin:0;padding:.4rem 0;border-bottom:1px solid var(--line)}[data-pid],p[id^="p"]{position:relative}.limad-paragraph-number{display:inline-flex!important;align-items:center;justify-content:center;min-width:1.55em;margin-right:.35em;color:#6747cc;font-weight:700;font-size:.78em;cursor:pointer;border-radius:5px}.limad-paragraph-number:hover{background:var(--accent-soft)}.limad-note-pin{display:inline-flex;width:19px;height:19px;margin-left:6px;align-items:center;justify-content:center;border-radius:50%;background:var(--accent);color:#fff;font-size:11px;vertical-align:middle;cursor:pointer}[data-limad-mark]{cursor:pointer;box-decoration-break:clone;-webkit-box-decoration-break:clone;padding:.04em .03em;border-radius:2px;background-image:linear-gradient(176deg,transparent 5%,var(--marker) 9%,var(--marker) 88%,transparent 94%)}[data-limad-mark="0"]{--marker:rgba(255,225,92,.72)}[data-limad-mark="1"]{--marker:rgba(118,220,168,.58)}[data-limad-mark="2"]{--marker:rgba(112,177,255,.5)}[data-limad-mark="3"]{--marker:rgba(246,149,193,.5)}[data-limad-mark="4"]{--marker:rgba(181,143,242,.48)}[data-limad-mark="5"]{--marker:rgba(255,166,91,.56)}.limad-popover{position:fixed;z-index:50;max-width:420px;max-height:55vh;overflow:auto;background:#fff;color:#24232a;border:1px solid #ddd7ea;border-radius:14px;padding:16px 18px;box-shadow:0 18px 55px rgba(45,35,72,.2)}.limad-popover button{float:right;border:0;background:none;font-size:20px;cursor:pointer}.limad-selection-menu{position:fixed;z-index:60;background:#25222c;color:white;border-radius:10px;padding:5px;box-shadow:0 10px 30px #0003;display:flex;gap:3px}.limad-selection-menu button{border:0;border-radius:7px;padding:7px 10px;background:transparent;color:white;cursor:pointer}.limad-selection-menu button:hover{background:#ffffff20}.limad-selection-menu .danger{color:#ff9b9b}.limad-selection-menu button[data-c]{width:30px;height:30px;padding:0;border:2px solid #ffffff55;border-radius:50%;font-size:0}.limad-selection-menu button[data-c="0"]{background:#ffe15c}.limad-selection-menu button[data-c="1"]{background:#76dca8}.limad-selection-menu button[data-c="2"]{background:#70b1ff}.limad-selection-menu button[data-c="3"]{background:#f695c1}.limad-selection-menu button[data-c="4"]{background:#b58ff2}.limad-selection-menu button[data-c="5"]{background:#ffa65b}
.limad-publication-banner{margin:-42px -58px 34px;padding:28px 58px 25px;color:#fff;border-radius:0 0 14px 14px;box-shadow:0 10px 28px rgba(24,40,58,.14)}.limad-publication-banner.meeting-workbook{background:linear-gradient(135deg,#087b93,#25a5b3)}.limad-publication-banner.watchtower-study{background:linear-gradient(135deg,#315d91,#5d7eb0)}.limad-publication-banner small{display:block;font:800 .72rem Inter,system-ui,sans-serif;letter-spacing:.09em;opacity:.9}.limad-publication-banner h1{margin:.28em 0 .18em;color:#fff}.limad-publication-banner p{margin:0;opacity:.88;font-size:.92rem}@media(max-width:700px){.limad-publication-banner{margin:-25px -22px 28px;padding:22px}.limad-publication-banner h1{font-size:1.65rem}body{padding:25px 22px 90px;font-size:calc(17px * var(--font-scale))}.limad-paragraph-number{position:static;margin-right:7px}}
'''

def _marks(db,doc):
    local=db.rows("SELECT id,block_identifier,start_token,end_token,color_index FROM local_marks WHERE document_id=?",(doc['id'],))
    imported=db.rows('''SELECT CAST(um.user_mark_id AS TEXT)||':'||um.backup_id AS id,br.identifier AS block_identifier,br.start_token,br.end_token,um.color_index FROM publications p JOIN user_locations l ON l.key_symbol=p.key_symbol AND l.meps_language=p.language_index AND l.document_id=? JOIN user_marks um ON um.backup_id=l.backup_id AND um.location_id=l.location_id JOIN block_ranges br ON br.backup_id=um.backup_id AND br.user_mark_id=um.user_mark_id WHERE p.id=?''',(doc.get('meps_document_id') or doc.get('source_document_id'),doc['publication_id']))
    return imported+local

def _notes(db,doc):
    local=db.rows("SELECT id,block_identifier,title,content FROM local_notes WHERE document_id=?",(doc['id'],))
    imported=db.rows('''SELECT CAST(n.note_id AS TEXT)||':'||n.backup_id AS id,n.block_identifier,n.title,n.content FROM publications p JOIN user_locations l ON l.key_symbol=p.key_symbol AND l.meps_language=p.language_index AND l.document_id=? JOIN notes n ON n.backup_id=l.backup_id AND n.location_id=l.location_id WHERE p.id=?''',(doc.get('meps_document_id') or doc.get('source_document_id'),doc['publication_id']))
    return imported+local

def render_document(document_id:int,database:Database=DB)->str:
    rows=database.rows('''SELECT d.*,p.title AS publication_title,p.content_dir,p.key_symbol,p.language_index FROM documents d JOIN publications p ON p.id=d.publication_id WHERE d.id=?''',(int(document_id),))
    if not rows: raise ValueError('Dokument wurde nicht gefunden.')
    doc=rows[0]; markup=doc['content_html'] or ''; prefix=f"/content/{escape(doc['publication_id'])}/"
    key=str(doc.get('key_symbol') or '').lower()
    label=' '.join(str(doc.get(name) or '') for name in ('publication_title','title','toc_title','class_name')).lower()
    reader_kind=''
    if key.startswith('mwb') or 'leben und dienst' in label or 'meeting workbook' in label:
        reader_kind='meeting-workbook'
    elif key.startswith('w') or 'wachtturm' in label or 'watchtower' in label:
        reader_kind='watchtower-study'
    if reader_kind:
        eyebrow='LEBEN UND DIENST' if reader_kind=='meeting-workbook' else 'WACHTTURM-STUDIUM'
        heading=escape(doc.get('title') or doc.get('toc_title') or doc.get('publication_title') or '')
        sub=escape(doc.get('subtitle') or doc.get('publication_title') or '')
        markup=f'<header class="limad-publication-banner {reader_kind}"><small>{eyebrow}</small><h1>{heading}</h1>{f"<p>{sub}</p>" if sub and sub!=heading else ""}</header>'+markup
    markup=re.sub(r'''(src|poster)=(['"])jwpub-media://([^'"?#]+)(?:[^'"]*)\2''',lambda m:f'{m.group(1)}={m.group(2)}{prefix}{escape(m.group(3))}{m.group(2)}',markup,flags=re.I)
    marks=json.dumps(_marks(database,doc),ensure_ascii=False); notes=json.dumps(_notes(database,doc),ensure_ascii=False); input_fields=json.dumps(database.rows("SELECT text_tag,value FROM local_input_fields WHERE document_id=?",(int(document_id),)),ensure_ascii=False)
    footnotes=json.dumps(database.rows("SELECT source_footnote_id,footnote_index,content_html FROM footnotes WHERE publication_id=? AND document_source_id=?",(doc['publication_id'],doc['source_document_id'])),ensure_ascii=False)
    script=f'''
const DOC={int(document_id)},marks={marks},notes={notes},footnotes={footnotes},savedInputFields={input_fields};
const blockNodes=()=>[...document.querySelectorAll('[data-pid],p[id^="p"]')];
for(const node of blockNodes()){{const raw=node.dataset.pid||(node.id||'').replace(/^p/,'');if(document.body.dataset.limadBibleReader!=='1'&&/^\\d+$/.test(raw)&&!node.querySelector(':scope > .limad-paragraph-number')){{const n=document.createElement('span');n.className='limad-paragraph-number';n.textContent=raw;n.title='Quellen und Verweise anzeigen';n.onclick=e=>{{e.preventDefault();e.stopPropagation();const links=[...node.querySelectorAll('a')].map(a=>({{href:a.getAttribute('href')||'',label:(a.textContent||'').trim()}})).filter(x=>x.href);post('limad-context',{{blockIdentifier:Number(raw),text:(node.innerText||'').replace(new RegExp('^\\s*'+raw+'\\s*'),''),links}})}};node.prepend(n)}}}}
function textTokens(node){{const walker=document.createTreeWalker(node,NodeFilter.SHOW_TEXT,{{acceptNode:n=>n.parentElement?.closest('.limad-paragraph-number,.verse-number,.limad-note-pin,script,style')?NodeFilter.FILTER_REJECT:NodeFilter.FILTER_ACCEPT}});let items=[],index=0,current;while(current=walker.nextNode()){{const re=/\\S+/g;let m;while((m=re.exec(current.data)))items.push({{node:current,start:m.index,end:m.index+m[0].length,index:index++}})}}return items}}
function applyTokenMark(node,item){{const tokens=textTokens(node),start=item.start_token==null?0:Number(item.start_token),end=item.end_token==null?tokens.length-1:Number(item.end_token);const selected=tokens.filter(t=>t.index>=start&&t.index<=end);if(!selected.length)return;const groups=[];for(const token of selected){{let group=groups[groups.length-1];if(!group||group.node!==token.node){{group={{node:token.node,start:token.start,end:token.end}};groups.push(group)}}else group.end=token.end}}for(const group of groups.reverse()){{const range=document.createRange();range.setStart(group.node,group.start);range.setEnd(group.node,group.end);const span=document.createElement('span');span.dataset.limadMark=String((item.color_index||0)%6);span.dataset.markId=String(item.id||'');span.dataset.markBlock=String(item.block_identifier??'');span.dataset.markStart=String(item.start_token??'');span.dataset.markEnd=String(item.end_token??'');try{{range.surroundContents(span)}}catch{{}}}}}}
for(const item of marks){{const id=CSS.escape(String(item.block_identifier??''));const node=document.querySelector(`.bible-verse[data-pid="${{id}}"]`)||document.querySelector(`[data-pid="${{id}}"],#p${{id}}`);if(node)applyTokenMark(node,item)}}
for(const item of notes){{const node=document.querySelector(`[data-pid="${{item.block_identifier}}"],#p${{item.block_identifier}}`);if(node){{const pin=document.createElement('span');pin.className='limad-note-pin';pin.textContent='N';pin.title=item.title||item.content||'Notiz';pin.onclick=e=>{{e.stopPropagation();parent.postMessage({{type:'limad-note-open',note:item}},location.origin)}};node.append(pin)}}}}
function post(type,data={{}}){{parent.postMessage({{type,...data}},location.origin)}}
let selectionMenuTimer=null;function closePop(){{clearTimeout(selectionMenuTimer);document.querySelectorAll('.limad-popover,.limad-selection-menu').forEach(n=>n.remove())}}
function armSelectionMenu(menu){{clearTimeout(selectionMenuTimer);selectionMenuTimer=setTimeout(()=>menu.remove(),4000);['pointermove','mouseenter','focusin'].forEach(type=>menu.addEventListener(type,()=>{{clearTimeout(selectionMenuTimer);selectionMenuTimer=setTimeout(()=>menu.remove(),4000)}}))}}
function positionSelectionMenu(menu,x,y){{document.body.append(menu);menu.style.left=Math.min(x,innerWidth-menu.offsetWidth-8)+'px';menu.style.top=Math.max(8,y-48)+'px';armSelectionMenu(menu)}}
function markMenu(mark,x,y){{closePop();const m=document.createElement('div');m.className='limad-selection-menu';const imported=String(mark.id||'').includes(':');m.innerHTML='<button data-c="0" title="Gelb">Gelb</button><button data-c="1" title="Grün">Grün</button><button data-c="2" title="Blau">Blau</button><button data-c="3" title="Rosa">Rosa</button><button data-c="4" title="Violett">Violett</button><button data-c="5" title="Orange">Orange</button><button data-note>Notiz</button>'+(imported?'':'<button class="danger" data-remove>Entfernen</button>');positionSelectionMenu(m,x,y);m.querySelectorAll('[data-c]').forEach(button=>button.onclick=()=>{{post('limad-mark-update',{{markId:String(mark.id),colorIndex:Number(button.dataset.c)}});m.remove()}});m.querySelector('[data-note]').onclick=()=>{{post('limad-selection',{{documentId:DOC,blockIdentifier:Number(mark.block_identifier),text:mark.text||''}});m.remove()}};m.querySelector('[data-remove]')?.addEventListener('click',()=>{{post('limad-mark-delete',{{markId:String(mark.id)}});m.remove()}})}}
function pop(html,x,y){{closePop();const p=document.createElement('div');p.className='limad-popover';p.innerHTML='<button aria-label="Schließen">×</button>'+html;p.querySelector('button').onclick=()=>p.remove();document.body.append(p);p.style.left=Math.min(x,innerWidth-p.offsetWidth-15)+'px';p.style.top=Math.min(y,innerHeight-p.offsetHeight-15)+'px'}}
function cleanCitationLabel(value){{return String(value||'').replace(/[;,\\s]+$/,'').trim()}}
function qualifyCitationAnchor(anchor){{
 const own=cleanCitationLabel(anchor.textContent||'');
 if(!own)return own;
 if(/^.*[A-Za-zÄÖÜäöüß]\\.?\\s+\\d{{1,3}}\\s*:\\s*\\d/u.test(own))return own;
 const container=anchor.closest('[data-pid],p[id^="p"],li,blockquote,td')||anchor.parentElement;
 const anchors=container?[...container.querySelectorAll('a')]:[anchor];
 let book='',chapter='';
 for(const item of anchors){{
  const raw=cleanCitationLabel(item.textContent||'');
  if(!raw)continue;
  const full=raw.match(/^(.+?[A-Za-zÄÖÜäöüß]\\.?)\\s+(\\d{{1,3}})\\s*:\\s*(.+)$/u);
  let qualified=raw;
  if(full){{book=cleanCitationLabel(full[1]);chapter=full[2];qualified=`${{book}} ${{chapter}}:${{cleanCitationLabel(full[3])}}`}}
  else{{
   const chapterVerse=raw.match(/^(\\d{{1,3}})\\s*:\\s*(.+)$/u);
   if(chapterVerse&&book){{chapter=chapterVerse[1];qualified=`${{book}} ${{chapter}}:${{cleanCitationLabel(chapterVerse[2])}}`}}
   else{{
    const verseOnly=raw.match(/^(\\d{{1,3}}(?:\\s*[-–—]\\s*\\d{{1,3}})?)$/u);
    if(verseOnly&&book&&chapter)qualified=`${{book}} ${{chapter}}:${{cleanCitationLabel(verseOnly[1])}}`;
   }}
  }}
  if(item===anchor)return qualified;
 }}
 return own;
}}
document.addEventListener('pointerdown',e=>{{const a=e.target.closest('a');if(!a)return;const href=a.getAttribute('href')||'';if(href.startsWith('jwpub://')||href.startsWith('jwlibrary://')||href.includes('wol.jw.org')||href.includes('jw.org')){{e.preventDefault();e.stopPropagation()}}}},true);
document.addEventListener('click',e=>{{const marked=e.target.closest('[data-mark-id]');if(marked){{e.preventDefault();e.stopPropagation();markMenu({{id:marked.dataset.markId,block_identifier:marked.dataset.markBlock,start_token:marked.dataset.markStart,end_token:marked.dataset.markEnd,text:marked.textContent||''}},e.clientX,e.clientY);return}}const a=e.target.closest('a');if(!a)return;const href=a.getAttribute('href')||'';const f=/footnote|fn/i.test(href+a.className);if(f){{e.preventDefault();const num=(href.match(/\\d+/)||[])[0];const item=footnotes.find(x=>String(x.footnote_index)==num||String(x.source_footnote_id)==num);if(item)pop(item.content_html,e.clientX,e.clientY);return}}if(href.startsWith('jwpub://')||href.startsWith('jwlibrary://')||href.includes('wol.jw.org')||href.includes('jw.org')){{const keepX=scrollX,keepY=scrollY;e.preventDefault();e.stopPropagation();e.stopImmediatePropagation();const original=(a.textContent||'').trim();const qualified=qualifyCitationAnchor(a);post('limad-link',{{href,label:qualified||original,text:qualified||original,originalLabel:original,readerScrollX:keepX,readerScrollY:keepY}});requestAnimationFrame(()=>scrollTo(keepX,keepY));setTimeout(()=>scrollTo(keepX,keepY),0);setTimeout(()=>scrollTo(keepX,keepY),80)}}}},true);
document.addEventListener('mouseup',e=>{{if(document.body.dataset.limadBibleReader==='1')return;setTimeout(()=>{{const sel=getSelection();if(!sel||sel.isCollapsed)return;const node=sel.anchorNode?.parentElement?.closest('[data-pid],p[id^="p"]');if(!node)return;const block=Number(node.dataset.pid||(node.id||'').replace(/^p/,''));const text=sel.toString().trim();if(!text)return;closePop();const m=document.createElement('div');m.className='limad-selection-menu';m.innerHTML='<button data-c="0" title="Gelb">Gelb</button><button data-c="1" title="Grün">Grün</button><button data-c="2" title="Blau">Blau</button><button data-c="3" title="Rosa">Rosa</button><button data-c="4" title="Violett">Violett</button><button data-c="5" title="Orange">Orange</button><button data-note>Notiz</button>';positionSelectionMenu(m,e.clientX,e.clientY);m.querySelectorAll('[data-c]').forEach(b=>b.onclick=()=>{{(()=>{{const tokens=textTokens(node),range=sel.getRangeAt(0);let start=null,end=null;tokens.forEach(t=>{{const r=document.createRange();r.setStart(t.node,t.start);r.setEnd(t.node,t.end);if(range.compareBoundaryPoints(Range.END_TO_START,r)<0&&range.compareBoundaryPoints(Range.START_TO_END,r)>0){{if(start===null)start=t.index;end=t.index}}}});post('limad-mark',{{documentId:DOC,blockIdentifier:block,text,startToken:start,endToken:end,colorIndex:Number(b.dataset.c)}})}})();m.remove()}});m.querySelector('[data-note]').onclick=()=>{{post('limad-selection',{{documentId:DOC,blockIdentifier:block,text}});m.remove()}}}},0)}});
document.addEventListener('pointerdown',e=>{{if(!e.target.closest('.limad-selection-menu')&&!e.target.closest('[data-limad-mark]'))document.querySelectorAll('.limad-selection-menu').forEach(node=>node.remove())}},true);
document.addEventListener('keydown',e=>{{if(e.key==='Escape')closePop()}});
const savedFieldMap=new Map(savedInputFields.map(item=>[String(item.text_tag),String(item.value||'')]));
function inputFieldTag(node,index){{const direct=node.dataset?.textTag||node.dataset?.texttag||node.dataset?.inputField||node.getAttribute('data-text-tag')||node.getAttribute('data-texttag')||node.getAttribute('data-input-field')||node.getAttribute('name')||node.id;if(direct)return String(direct);const block=node.closest('[data-pid],p[id^="p"]');const blockId=block?.dataset?.pid||(block?.id||'').replace(/^p/,'')||'document';return `answer:${{blockId}}:${{index}}`}}
const answerFields=[...document.querySelectorAll('textarea,input[type="text"],input:not([type]),[contenteditable="true"]')].filter(node=>!node.closest('.limad-selection-menu,.limad-popover'));
answerFields.forEach((node,index)=>{{const tag=inputFieldTag(node,index);node.dataset.limadInputTag=tag;const saved=savedFieldMap.get(tag);if(saved!==undefined){{if(node.matches('[contenteditable]'))node.textContent=saved;else node.value=saved}}let saveTimer=null;const save=()=>{{const value=node.matches('[contenteditable]')?node.innerText:String(node.value||'');fetch('/api/input-fields',{{method:'POST',headers:{{'Content-Type':'application/json'}},body:JSON.stringify({{document_id:DOC,text_tag:tag,value}}),keepalive:true}}).then(()=>post('limad-input-field-saved',{{documentId:DOC,textTag:tag,value}})).catch(()=>{{}})}};node.addEventListener('input',()=>{{clearTimeout(saveTimer);saveTimer=setTimeout(save,350)}});node.addEventListener('change',save);node.addEventListener('blur',save)}});
let timer;addEventListener('scroll',()=>{{clearTimeout(timer);timer=setTimeout(()=>{{const max=document.documentElement.scrollHeight-innerHeight;post('limad-position',{{documentId:DOC,scrollRatio:max>0?scrollY/max:0,blockIdentifier:null}})}},350)}});
addEventListener('message',e=>{{const d=e.data||{{}};if(d.type==='limad-restore'){{if(d.blockIdentifier)document.querySelector(`[data-pid="${{d.blockIdentifier}}"],#p${{d.blockIdentifier}}`)?.scrollIntoView();else scrollTo(0,(document.documentElement.scrollHeight-innerHeight)*(d.scrollRatio||0))}}if(d.type==='limad-font')document.documentElement.style.setProperty('--font-scale',String(d.scale||1));if(d.type==='limad-theme')document.documentElement.dataset.theme=d.theme==='dark'?'dark':'light'}});
post('limad-reader-ready',{{documentId:DOC}});
'''
    title=escape(doc.get('title') or doc.get('publication_title') or 'LiMaD Study')
    return f'<!doctype html><html lang="de"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><base href="{prefix}"><title>{title}</title><style>{READER_CSS}</style></head><body>{markup}<script>{script}</script></body></html>'
